<script setup lang="ts">import { onMounted, ref } from 'vue';import { useCalendarStore } from '../stores/calendar';const store=useCalendarStore();const month=ref(new Date().toISOString().slice(0,7));onMounted(()=>store.load('emp-demo',month.value))</script>
<template><section><div class="title"><div><small>个人月历</small><h1>投入日历</h1></div><el-date-picker v-model="month" type="month" value-format="YYYY-MM" @change="store.load('emp-demo', month)"/></div><el-alert v-if="store.calendar?.missing_days" type="warning" :title="`本月有 ${store.calendar.missing_days} 个工作日缺报`" show-icon/><el-card class="calendar"><div v-for="day in (store.calendar?.days??[])" :key="day.date" class="day" :class="{missing:day.missing}"><span>{{day.date.slice(8,10)}}</span><b>{{day.reported_minutes}}m</b><small v-if="day.overtime_minutes">加班 {{day.overtime_minutes}}m</small></div></el-card></section></template>
<style scoped>.title{display:flex;justify-content:space-between;align-items:flex-end;margin:12px 0 24px}h1{margin:6px 0;font-size:28px;color:#17324d}.calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:8px;margin-top:18px}.day{min-height:78px;border:1px solid #e5eaf0;padding:10px;background:#fff;display:flex;flex-direction:column;gap:6px}.day.missing{border-color:#e6a23c;background:#fff9eb}.day small{color:#b26a00}@media(max-width:700px){.calendar{grid-template-columns:repeat(3,1fr)}.title{align-items:flex-start;gap:12px;flex-direction:column}}</style>
